import mermaid from"https://cdn.jsdelivr.net/npm/mermaid@11.4.1/dist/mermaid.esm.min.mjs";const palettes={light:{bg:"#ffffff",ink:"#1e1e1e",muted:"#6c6c6c",line:"#5a6373",node:"#e7eefb",nodeBorder:"#1d5bcc",cluster:"#f6f8fb",clusterBorder:"#dde2ea"},dark:{bg:"#2e2e33",ink:"#dadadb",muted:"#9b9c9d",line:"#a7afbd",node:"#1f2b47",nodeBorder:"#7ea8ff",cluster:"#26272b",clusterBorder:"#3a3f48"}},FONT=getComputedStyle(document.body).fontFamily,nodes=[...document.querySelectorAll("pre.mermaid")];nodes.forEach(e=>e.dataset.src=e.textContent);async function render(){const e=palettes[document.documentElement.dataset.theme==="dark"?"dark":"light"];mermaid.initialize({startOnLoad:!1,securityLevel:"strict",theme:"base",fontFamily:FONT,flowchart:{curve:"basis",padding:10,nodeSpacing:28,rankSpacing:34},themeVariables:{background:e.bg,primaryColor:e.node,primaryBorderColor:e.nodeBorder,primaryTextColor:e.ink,secondaryColor:e.cluster,tertiaryColor:e.cluster,lineColor:e.line,textColor:e.ink,clusterBkg:e.cluster,clusterBorder:e.clusterBorder,edgeLabelBackground:e.bg,titleColor:e.muted,fontSize:"15px"}}),nodes.forEach(e=>{e.removeAttribute("data-processed"),e.textContent=e.dataset.src}),await mermaid.run({nodes})}render(),new MutationObserver(render).observe(document.documentElement,{attributes:!0,attributeFilter:["data-theme"]})